/**
 * Converts the two upstream type shapes schema generation consumes —
 * auto-generated types (inline objects/enums/unions synthesized during
 * auto-type generation) and types extracted directly from user source —
 * into the unified `BaseType`/`InputType` shapes the rest of schema
 * generation and resolver-map construction rely on.
 *
 * The two source shapes are near- but not perfectly identical:
 * - `AutoGeneratedType.kind` has no `"Interface"` member (auto-generated
 *   types are never interfaces).
 * - Auto-generated types carry no `directives`/`implementedInterfaces`/
 *   `isNumericEnum` data (that information doesn't exist for synthesized
 *   types) and use a nested `sourceLocation` object instead of a flat
 *   `sourceFile` string. `deprecated` *is* carried, but only when sourced
 *   from a genuine inline-object-alias/external-enum TSDoc tag (Object/
 *   InputObject/Enum kinds built by `generateAutoType`/`generateAutoEnumType`
 *   — refactor-plan.md §1.3 bug #9); the remaining synthesized shapes
 *   (union members, oneOf wrappers, standalone inline unions) have no such
 *   source and always carry `deprecated: null`.
 * - Auto-generated enum values (`AutoGeneratedEnumValue`) structurally lack
 *   `numericValue` (auto-generated enums are never numeric).
 * - Only auto-generated `Union` types carry a `resolveTypeFieldPattern`,
 *   which drives `autoGeneratedUnions` registration; extracted types never
 *   participate in that.
 *
 * Those genuine differences are resolved once, by the two adapters below,
 * so the shared per-kind conversion (`mapType`) has no source-specific
 * branching.
 */

import {
  type AutoGeneratedType,
  createFieldNameSet,
  type ResolveTypeFieldPattern,
} from "../../auto-type-generator/index.js";
import type {
  DeprecationInfo,
  DirectiveInfo,
  EnumValueInfo,
  FieldInfo,
  GraphQLTypeInfo,
  GraphQLTypeKind,
} from "../../core/index.js";

export interface BaseType {
  readonly name: string;
  readonly kind: "Object" | "Interface" | "Union" | "Enum";
  readonly fields: ReadonlyArray<FieldInfo> | null;
  readonly unionMembers: ReadonlyArray<string> | null;
  readonly enumValues: ReadonlyArray<EnumValueInfo> | null;
  /** True if this enum uses numeric values */
  readonly isNumericEnum: boolean;
  /** True if this string enum needs value mapping (at least one value converted) */
  readonly needsStringEnumMapping: boolean;
  readonly implementedInterfaces: ReadonlyArray<string> | null;
  readonly description: string | null;
  readonly deprecated: DeprecationInfo | null;
  readonly sourceFile: string | null;
  readonly directives: ReadonlyArray<DirectiveInfo> | null;
}

export interface InputType {
  readonly name: string;
  readonly fields: ReadonlyArray<FieldInfo>;
  readonly sourceFile: string;
  readonly description: string | null;
  readonly deprecated: DeprecationInfo | null;
  readonly isOneOf: boolean;
}

export interface AutoGeneratedUnionInfo {
  readonly name: string;
  readonly fieldPattern: ResolveTypeFieldPattern;
  readonly hasAutoResolveType: boolean;
}

/**
 * Normalized shape both `AutoGeneratedType` and `GraphQLTypeInfo` are
 * adapted into before the single per-kind conversion in `mapType`.
 */
interface TypeMappingInput {
  readonly name: string;
  readonly kind: GraphQLTypeKind;
  readonly fields: ReadonlyArray<FieldInfo> | null;
  readonly unionMembers: ReadonlyArray<string> | null;
  readonly enumValues: ReadonlyArray<EnumValueInfo> | null;
  readonly isNumericEnum: boolean;
  readonly needsStringEnumMapping: boolean;
  readonly implementedInterfaces: ReadonlyArray<string> | null;
  readonly description: string | null;
  readonly deprecated: DeprecationInfo | null;
  readonly sourceFile: string;
  readonly directives: ReadonlyArray<DirectiveInfo> | null;
  /**
   * Set only for auto-generated Union types; drives `autoGeneratedUnions`
   * registration, which extracted types never participate in.
   */
  readonly autoGeneratedUnionPattern: {
    readonly fieldPattern: ResolveTypeFieldPattern | null;
  } | null;
}

function autoGeneratedTypeToMappingInput(
  autoType: AutoGeneratedType,
): TypeMappingInput {
  return {
    name: autoType.name,
    kind: autoType.kind,
    fields: autoType.fields,
    unionMembers: autoType.unionMembers ?? [],
    enumValues:
      autoType.enumValues?.map((v) => ({
        name: v.name,
        originalValue: v.originalValue,
        numericValue: null,
        description: v.description,
        deprecated: v.deprecated,
      })) ?? null,
    isNumericEnum: false,
    needsStringEnumMapping: autoType.needsStringEnumMapping,
    implementedInterfaces: null,
    description: autoType.description,
    deprecated: autoType.deprecated,
    sourceFile: autoType.sourceLocation.file,
    directives: null,
    autoGeneratedUnionPattern:
      autoType.kind === "Union"
        ? { fieldPattern: autoType.resolveTypeFieldPattern }
        : null,
  };
}

function extractedTypeToMappingInput(type: GraphQLTypeInfo): TypeMappingInput {
  return {
    name: type.name,
    kind: type.kind,
    fields: type.fields,
    unionMembers: type.unionMembers,
    enumValues: type.enumValues,
    isNumericEnum: type.isNumericEnum,
    needsStringEnumMapping: type.needsStringEnumMapping,
    implementedInterfaces: type.implementedInterfaces,
    description: type.description,
    deprecated: type.deprecated,
    sourceFile: type.sourceFile,
    directives: type.directives,
    autoGeneratedUnionPattern: null,
  };
}

interface MappedType {
  readonly baseType: BaseType | null;
  readonly inputType: InputType | null;
  readonly autoGeneratedUnion: AutoGeneratedUnionInfo | null;
}

function mapType(input: TypeMappingInput): MappedType {
  switch (input.kind) {
    case "Enum":
      return {
        baseType: {
          name: input.name,
          kind: "Enum",
          fields: null,
          unionMembers: null,
          enumValues: input.enumValues,
          isNumericEnum: input.isNumericEnum,
          needsStringEnumMapping: input.needsStringEnumMapping,
          implementedInterfaces: null,
          description: input.description,
          deprecated: input.deprecated,
          sourceFile: input.sourceFile,
          directives: input.directives,
        },
        inputType: null,
        autoGeneratedUnion: null,
      };

    case "Union": {
      const autoGeneratedUnion = input.autoGeneratedUnionPattern
        ? {
            name: input.name,
            fieldPattern: input.autoGeneratedUnionPattern.fieldPattern ?? {
              usedFieldNames: createFieldNameSet(["__typename"]),
            },
            hasAutoResolveType:
              input.autoGeneratedUnionPattern.fieldPattern !== null,
          }
        : null;
      return {
        baseType: {
          name: input.name,
          kind: "Union",
          fields: null,
          unionMembers: input.unionMembers,
          enumValues: null,
          isNumericEnum: false,
          needsStringEnumMapping: false,
          implementedInterfaces: null,
          description: input.description,
          deprecated: null,
          sourceFile: input.sourceFile,
          directives: input.directives,
        },
        inputType: null,
        autoGeneratedUnion,
      };
    }

    case "Object":
    case "Interface":
      return {
        baseType: {
          name: input.name,
          kind: input.kind,
          fields: input.fields,
          unionMembers: null,
          enumValues: null,
          isNumericEnum: false,
          needsStringEnumMapping: false,
          implementedInterfaces: input.implementedInterfaces,
          description: input.description,
          deprecated: input.deprecated,
          sourceFile: input.sourceFile,
          directives: input.directives,
        },
        inputType: null,
        autoGeneratedUnion: null,
      };

    case "InputObject":
    case "OneOfInputObject":
      return {
        baseType: null,
        inputType: {
          name: input.name,
          fields: input.fields ?? [],
          sourceFile: input.sourceFile,
          description: input.description,
          deprecated: input.deprecated,
          isOneOf: input.kind === "OneOfInputObject",
        },
        autoGeneratedUnion: null,
      };
  }
}

export interface MapTypesParams {
  readonly autoGeneratedTypes: ReadonlyArray<AutoGeneratedType> | null;
  readonly extractedTypes: ReadonlyArray<GraphQLTypeInfo>;
  /**
   * Names of types that back a directive definition's TS type alias — these
   * are metadata-only and must not become schema types themselves. Only
   * ever relevant for extracted types; auto-generated types can never be
   * directive-definition aliases.
   */
  readonly directiveTypeAliasNames: ReadonlySet<string>;
}

export interface MapTypesResult {
  readonly baseTypes: ReadonlyArray<BaseType>;
  readonly inputTypes: ReadonlyArray<InputType>;
  readonly autoGeneratedUnions: ReadonlyArray<AutoGeneratedUnionInfo>;
}

/**
 * Converts both auto-generated types and extracted types into the unified
 * `BaseType`/`InputType` shapes. Auto-generated types are always mapped
 * before extracted types — this ordering is load-bearing for generated
 * output.
 */
export function mapTypes(params: MapTypesParams): MapTypesResult {
  const { autoGeneratedTypes, extractedTypes, directiveTypeAliasNames } =
    params;

  const baseTypes: BaseType[] = [];
  const inputTypes: InputType[] = [];
  const autoGeneratedUnions: AutoGeneratedUnionInfo[] = [];

  for (const autoType of autoGeneratedTypes ?? []) {
    const mapped = mapType(autoGeneratedTypeToMappingInput(autoType));
    if (mapped.baseType) {
      baseTypes.push(mapped.baseType);
    }
    if (mapped.inputType) {
      inputTypes.push(mapped.inputType);
    }
    if (mapped.autoGeneratedUnion) {
      autoGeneratedUnions.push(mapped.autoGeneratedUnion);
    }
  }

  for (const type of extractedTypes) {
    if (directiveTypeAliasNames.has(type.name)) {
      continue;
    }
    const mapped = mapType(extractedTypeToMappingInput(type));
    if (mapped.baseType) {
      baseTypes.push(mapped.baseType);
    }
    if (mapped.inputType) {
      inputTypes.push(mapped.inputType);
    }
  }

  return { baseTypes, inputTypes, autoGeneratedUnions };
}
